package ec.dmt.admin.school;
import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import java.util.*;
@RestController @RequestMapping("/api/guardians") public class GuardianController { private final GuardianRepository repo; private final StudentRepository students; public GuardianController(GuardianRepository repo,StudentRepository students){this.repo=repo;this.students=students;} @GetMapping public List<View> list(){return repo.findAll().stream().map(View::of).toList();} @PostMapping public ResponseEntity<View> create(@Valid @RequestBody Input in){Guardian g=repo.save(new Guardian(student(in.studentId()),in.firstName().trim(),in.lastName().trim(),in.email().trim(),in.active()));return ResponseEntity.status(201).body(View.of(g));} @PutMapping("/{id}") public View update(@PathVariable Long id,@Valid @RequestBody Input in){Guardian g=find(id);g.update(student(in.studentId()),in.firstName().trim(),in.lastName().trim(),in.email().trim(),in.active());return View.of(repo.save(g));} @DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable Long id){repo.delete(find(id));} private Guardian find(Long id){return repo.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Representante no encontrado"));} private Student student(Long id){return students.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.BAD_REQUEST,"Estudiante no encontrado"));} public record Input(@NotNull Long studentId,@NotBlank String firstName,@NotBlank String lastName,@NotBlank @Email String email,boolean active){} public record View(Long id,Long studentId,String studentName,String firstName,String lastName,String email,boolean active){static View of(Guardian g){Student s=g.getStudent();return new View(g.getId(),s.getId(),s.getFirstName()+" "+s.getLastName(),g.getFirstName(),g.getLastName(),g.getEmail(),g.isActive());}} }
